package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.regex.Pattern;
import java.util.regex.PatternSyntaxException;
import org.jsoup.helper.StringUtil;
import org.jsoup.helper.Validate;
import org.jsoup.nodes.Element;
import org.jsoup.nodes.Tag;
import org.jsoup.nodes.TextNode;
import org.jsoup.parser.Parser;
import org.jsoup.parser.Tag;
import org.jsoup.select.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class Element_equals_TriageGen2Test {

    private Element element;
    private Element sameElement;
    private Object differentObject;
    private Element differentElement;

    @Before
    public void setUp() {
        element = new Element(Tag.valueOf("div"), "http://example.com", null);
        sameElement = new Element(Tag.valueOf("div"), "http://example.com", null);
        differentObject = new Object();
        differentElement = new Element(Tag.valueOf("span"), "http://example.com", null);
    }

    @Test
    public void testEqualsReturnsTrueForSameObject() {
        assertTrue(element.equals(element));
    }

    @Test
    public void testEqualsReturnsFalseForNullObject() {
        assertFalse(element.equals(null));
    }

    @Test
    public void testEqualsReturnsFalseForDifferentClassObject() {
        assertFalse(element.equals(differentObject));
    }

    @Test
    public void testEqualsReturnsTrueForSameElement() {
        assertTrue(element.equals(sameElement));
    }

    @Test
    public void testEqualsReturnsFalseForDifferentElement() {
        assertFalse(element.equals(differentElement));
    }

    @Test
    public void testEqualsInheritsSuperEqualsBehavior() {
        Element elementWithDifferentTag = new Element(Tag.valueOf("span"), "http://example.com", null);
        assertFalse(element.equals(elementWithDifferentTag));
    }

    @Test
    public void testEqualsWithTextNode() {
        TextNode textNode = new TextNode("text");
        assertFalse(element.equals(textNode));
    }

    @Test
    public void testEqualsWithDifferentBaseUri() {
        Element elementWithDifferentBaseUri = new Element(Tag.valueOf("div"), "http://different.com", null);
        assertFalse(element.equals(elementWithDifferentBaseUri));
    }
}
